/* cppi::3e13367c7c3c01611c310b80077d89f400a0557e60a6c814f8b1ee2fdb6edb46 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-05-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-12-31'
    ) a
where arrival_time = max_publish

/* cppi::2f5b44367e5a832931310d8ec516985d24e379f70a021d967b9a716c725b1659 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-04-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-12-31'
    ) a
where arrival_time = max_publish

/* cppi::b908af71c730b21ad22c3b27f8bb4709bad3046ccb024c333960d6f9b121a280 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2024-11-21' and end_date = '2024-11-21')
and start_date = '2024-11-21' and end_date = '2024-11-21'

