/* cppi::ba0fc7c4a9922743f59af1609c630ce7858a7ba531dea3fe4a9c5496e6393feb */
SELECT COUNT(*) FROM (WITH filtered_index AS (SELECT business_date, id_cppib_index, index_description, rimes_source_code, rimes_source_description, index_value_base, return_daily_base, inception_return_base, id_rimes_symbol, feed_version FROM market.cppib_index WHERE id_cppib_index IN ('G0O1_TR_CAD_0_0', 'G0O1_TR_USD_0_0', '1662_TR_CAD_0_0', '1662_TR_USD_0_0', '29478_TR_CAD_0_0', '29478_TR_USD_0_0', '3435_TR_CAD_0_0', '3435_TR_USD_0_0', '39_TR_CAD_0_0', '39_TR_USD_0_0', '23059_TR_CAD_0_0', '23059_TR_USD_0_0', 'ENHG_GR_CAD_0_0', 'ENHGL_GR_LOC_0_0', 'SBWGU_TR_CAD_0_0', 'SBWGU_TR_LOC_0_0', 'CEMBIBD_TR_CAD_0_0', 'CEMBIBD_TR_USD_0_0', 'GBI_EMB_TR_CAD_0_0', 'GBI_EMB_TR_USD_0_0', 'BMIRAPFF00X_CNR_CAD_0_0', 'BMIRAPFF00X_CNR_LOC_0_0', 'BMIRAPFF00S_CNR_CAD_0_0', 'BMIRAPFF00S_CNR_LOC_0_0', 'BMIRAEFF00X_CNR_CAD_0_0', 'BMIRAEFF00X_CNR_LOC_0_0', 'BMICNFFACX_CNR_CAD_0_0', 'BMICNFFACX_CNR_LOC_0_0', 'BMIRWDFF55105020_CNR_CAD_0_0', 'BMIRWDFF55105020_CNR_LOC_0_0', 'BMIRWDFF00X10_CNR_CAD_0_0', 'BMIRWDFF00X10_CNR_LOC_0_0', 'BMIRWDFF00X_CNR_CAD_0_0', 'BMIRWDFF00X_CNR_LOC_0_0', 'BMIRWDFF00S_CNR_CAD_0_0', 'BMIRWDFF00S_CNR_LOC_0_0', 'BMIRWDFF00X55_CNR_CAD_0_0', 'BMIRWDFF00X55_CNR_LOC_0_0', 'BMIREDFF55105020_CNR_CAD_0_0', 'BMIREDFF55105020_CNR_LOC_0_0', 'BMIREMFF00X_CNR_CAD_0_0', 'BMIREMFF00X_CNR_LOC_0_0', 'BMIREMFF00X55_CNR_CAD_0_0', 'BMIREMFF00X55_CNR_LOC_0_0', 'BMIRGLFF30202010_CNR_CAD_0_0', 'BMIRGLFF30202010_CNR_LOC_0_0', 'INMIRKCFF_CNR_CAD_0_0', 'INMIRKCFF_CNR_LOC_0_0', 'BMIUSFF00X40_CNR_CAD_0_0', 'PMIRCUS_40_GR_LOC_0_0', 'ALL_TR_CAD_0_0') AND business_date BETWEEN DATE '2025-04-30' AND DATE '2025-04-30'), latest_feed_versions AS (SELECT id_cppib_index, business_date, MAX(feed_version) AS feed_version FROM filtered_index GROUP BY id_cppib_index, business_date) SELECT f.business_date, f.id_cppib_index, f.index_description, f.id_rimes_symbol, f.return_daily_base, f.inception_return_base FROM filtered_index f JOIN latest_feed_versions lfv ON f.id_cppib_index = lfv.id_cppib_index AND f.business_date = lfv.business_date AND f.feed_version = lfv.feed_version
) dbvrcnt

